import assert from 'node:assert/strict';
import {readFileSync,readdirSync,writeFileSync} from 'node:fs';
import {pathToFileURL} from 'node:url';
import {createHash} from 'node:crypto';
import {verifyRuntime} from '/Users/tk/.codex/worktrees/3183/agent-loop/tools/agent4/dependencies.mjs';
const root='/Users/tk/.codex/worktrees/3183/agent-loop';
const selections={before:{runtime:root+'/.agent4-qualified-e89/out/world-runtime/runtime',lock:root+'/.agent4-qualified-e89/binding/candidate-full-profiles.lock.json'},after:{runtime:root+'/.agent4-qualified-cb52/out/world-runtime/runtime',lock:root+'/conformance/agent4/dependencies.lock.json'}};
const hash=b=>createHash('sha256').update(b).digest('hex'),arms={};
for(const [name,selected]of Object.entries(selections)){const identity=verifyRuntime(selected.runtime,{lockPath:selected.lock});arms[name]={identity,world:await import(pathToFileURL(identity.entrypoint)),bytes:readFileSync(identity.kernelPath)};}
const fresh=async arm=>{const a=arms[arm],k=await a.world.Kernel.create({bytes:a.bytes,expectedSha256:a.identity.kernelSha256});k.setLimits({input:256<<20,working:256<<20,output:256<<20});return k;};
const report={status:'running',scope:'Deterministic same-image memory and byte replay; no latency measurements and no external tools/models executed.',kernels:Object.fromEntries(Object.entries(arms).map(([key,a])=>[key,a.identity.kernelSha256])),admission:[],replay:[]};
for(const name of readdirSync('/tmp/g-final-corpus').filter(x=>x.endsWith('.bpi3')).sort()){
 const image=readFileSync('/tmp/g-final-corpus/'+name),row={name,imageSha256:hash(image)};
 for(const arm of ['before','after']){const k=await fresh(arm),p=k.prepare(image);row[arm]={peak:Number(k.usage().workingPeak),retained:Number(k.usage().workingLive)};k.releasePrepared(p);assert.equal(k.usage().workingLive,0n);}
 report.admission.push(row);
}
for(const path of ['/tmp/e89-inquiry-replay/manifest.json','/tmp/e89-additional-manifest.json']){
 const manifest=JSON.parse(readFileSync(path));
 for(const name of [...new Set(manifest.rows.map(r=>r.name))]){
  const rows=manifest.rows.filter(r=>r.name===name),result={name,commands:rows.length};
  for(const arm of ['before','after']){const k=await fresh(arm);for(const row of rows){const input=readFileSync(row.inputFile),expected=readFileSync(row.outputFile);assert.equal(hash(input),row.inputSha256);assert.equal(hash(expected),row.outputSha256);assert.deepEqual(Buffer.from(k.invoke(input)),expected);assert.equal(k.usage().workingLive,0n);}result[arm]={peak:Number(k.usage().workingPeak)};}
  report.replay.push(result);
 }
}
report.status='complete';writeFileSync('/tmp/final-consumer-memory.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({images:report.admission.length,scenarios:report.replay.length,commands:report.replay.reduce((n,r)=>n+r.commands,0),admissionGrowth:report.admission.filter(r=>r.after.peak>r.before.peak||r.after.retained>r.before.retained),executionGrowth:report.replay.filter(r=>r.after.peak>r.before.peak)}));
